fields.formulaExpression:
SWITCH(
  {fldcwJXqDIqh4HaS6},

  "In real time",
 {fldajoBsYVuEUB1x7},

  "Every Week",
  IF(
    {fld5MCPbi9UD9H7tf},
    DATEADD(
      DATETIME_PARSE(
        DATETIME_FORMAT({fld5MCPbi9UD9H7tf}, "YYYY-MM-DD"),
        "YYYY-MM-DD"
      ),
      1 + MOD(
        {fldkiWnJVJUkF8phY}
        - WEEKDAY(
          DATETIME_PARSE(
            DATETIME_FORMAT({fld5MCPbi9UD9H7tf}, "YYYY-MM-DD"),
            "YYYY-MM-DD"
          )
        )
        - 1
        + 7,
        7
      ),
      "days"
    ),
    {fldajoBsYVuEUB1x7}
  ),

  "Every Month",
  IF(
    {fld5MCPbi9UD9H7tf},
    IF(
      IS_AFTER({fldadNCDoMLONlQuN}, {fld5MCPbi9UD9H7tf}),
      {fldadNCDoMLONlQuN},
      {fldySqFEHQk5fWYXU}
    ),
    {fldajoBsYVuEUB1x7}
  )
)

